<?php
header('Content-Type: text/html; charset=UTF-8');
$ROOT=realpath(__DIR__);$SKIP=['.git','node_modules','vendor'];
function blocked($p){global $SKIP;foreach($SKIP as $s)if(preg_match('#(^|/)'.preg_quote($s,'#').'(/|$)#',$p))return true;return false;}
function scanSite($root){$files=[];$dirs=[];$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS));foreach($it as $f){$p=str_replace('\\','/',substr($f->getPathname(),strlen($root)+1));if(!$p||blocked($p)||$p==='site-wire-live.php')continue;if($f->isDir())$dirs[]=$p;else $files[$p]=$f->getSize();}sort($dirs);ksort($files);$refs=[];$rx=["/\\b(?:require|require_once|include|include_once)\\s*\\(?\\s*['\"]([^'\"]+)['\"]/i","/\\b(?:import|export)\\s+(?:[^'\";]+?\\s+from\\s+)?['\"]([^'\"]+)['\"]/i","/\\b(?:src|href)\\s*=\\s*['\"]([^'\"]+)['\"]/i"];foreach($files as $p=>$size){if($size>700000||!preg_match('/\\.(php|js|mjs|jsx|ts|tsx|css|scss|html|htm|json|xml|svg|yml|yaml|ini|conf|md)$/i',$p))continue;$s=@file_get_contents($root.'/'.$p);if($s===false)continue;foreach($rx as $re){preg_match_all($re,$s,$m);foreach(array_unique($m[1]??[]) as $v){$v=trim(preg_replace('/[#?].*$/','',$v));if(!$v||preg_match('/^(https?:|data:|mailto:|javascript:|#|\/\/)/i',$v))continue;$base=dirname($p);$c=ltrim(str_replace('\\','/',($v[0]==='/'?$v:$base.'/'.$v)),'/');foreach([$c,$c.'.php',$c.'.js',$c.'.css',$c.'.json',$c.'.html',$c.'/index.php',$c.'/index.html'] as $z){if(isset($files[$z])){$refs[]=['from'=>$p,'to'=>$z];break;}}}}}return ['files'=>array_keys($files),'dirs'=>$dirs,'refs'=>$refs,'time'=>date('H:i:s')];}
$D=scanSite($ROOT);
if(isset($_GET['pulse'])){header('Content-Type:application/json');header('Cache-Control:no-store');echo json_encode(['ok'=>1,'time'=>date('H:i:s'),'files'=>count($D['files']),'links'=>count($D['refs'])]);exit;}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SmartToolz — Relationship Manager</title><style>
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#050b10;color:#dce9ed;font-family:Inter,system-ui,Segoe UI,sans-serif}body{background:radial-gradient(circle at 50% 45%,#10242b 0,#071016 45%,#03070a 100%)}#map{position:fixed;inset:0;width:100%;height:100%;cursor:grab}.drag{cursor:grabbing!important}.top{position:fixed;z-index:4;left:22px;right:22px;top:18px;display:flex;justify-content:space-between;pointer-events:none}.brand{font-weight:800;font-size:19px}.brand b{color:#59dfd0}.sub,.small{color:#59727c;font:8px ui-monospace;margin-top:4px;letter-spacing:1px}.stats{display:flex;gap:6px}.stat,.search,.panel,.btn{background:#09151de8;border:1px solid #7897a41f;border-radius:9px;backdrop-filter:blur(12px)}.stat{padding:7px 10px}.stat small{display:block;color:#536c76;font:7px ui-monospace}.stat strong{font:11px ui-monospace}.live{color:#59e4b5}.search{position:fixed;z-index:5;left:22px;top:75px;width:250px;padding:10px 12px;color:#eaffff;outline:0;font:9px ui-monospace}.panel{display:none;position:fixed;z-index:6;right:22px;top:75px;width:330px;padding:15px}.panel.show{display:block}.close{float:right;border:0;background:none;color:#71868f;font-size:18px;cursor:pointer}.eyebrow{color:#58747d;font:7px ui-monospace;letter-spacing:1.4px}.panel h2{margin:7px 0 2px;font-size:15px}.path{color:#61ddd1;font:8px ui-monospace;word-break:break-all}.relations{margin-top:10px;color:#78919a;font:8px ui-monospace;line-height:1.7;max-height:300px;overflow:auto}.relations b{color:#c8d9de}.tools{position:fixed;z-index:5;left:22px;bottom:18px;display:flex;gap:6px}.btn{padding:8px 11px;color:#9cb4bd;font:800 8px ui-monospace;cursor:pointer}.btn:hover{color:#fff;border-color:#59dfd055}.hint{position:fixed;z-index:4;left:50%;bottom:20px;transform:translateX(-50%);padding:8px 12px;border:1px solid #7897a41a;border-radius:8px;background:#071118cc;color:#536d76;font:8px ui-monospace}.status{position:fixed;z-index:4;right:22px;bottom:22px;color:#607983;font:8px ui-monospace}.led{display:inline-block;width:6px;height:6px;border-radius:50%;background:#59e4b5;box-shadow:0 0 10px #59e4b5;margin-right:6px}.loader{position:fixed;z-index:20;inset:0;display:none;place-items:center;background:#04090df5}.node{cursor:pointer}.folder{fill:#11162a;stroke:#514581}.root{fill:#09191d;stroke:#3c7774}.file{fill:#09141a;stroke:#29434b}.wire{fill:none;stroke:#31505a;stroke-width:1}.dep{fill:none;stroke:#4d8f91;stroke-width:1.3;stroke-dasharray:6 8;animation:flow 1.4s linear infinite}.active{stroke:#59e2d1!important;stroke-width:2!important;opacity:1!important}@keyframes flow{to{stroke-dashoffset:-28px}}@media(max-width:700px){.top{left:11px;right:11px}.brand{font-size:16px}.sub{display:none}.stats .stat:nth-child(n+3){display:none}.search{left:11px;top:64px;width:195px}.panel{left:11px;right:11px;top:64px;width:auto}.tools{left:11px;bottom:11px}.hint{bottom:48px;white-space:nowrap}.status{right:11px;bottom:11px}}
</style></head><body>
<div class="loader" id="loader"><div><b>SmartToolz Relationship Manager</b><div class="small">Preparing map…</div></div></div>
<div class="top"><div><div class="brand"><b>◇</b> SmartToolz Relationship Manager</div><div class="sub">LIVE SERVER • GROUPED ARCHITECTURE • ACTUAL DEPENDENCIES</div></div><div class="stats"><div class="stat"><small>FILES</small><strong id="files">0</strong></div><div class="stat"><small>RELATIONS</small><strong id="rels">0</strong></div><div class="stat"><small>SERVER</small><strong class="live" id="state">LIVE</strong></div></div></div>
<input id="search" class="search" placeholder="Search file or folder…"><svg id="map" xmlns="http://www.w3.org/2000/svg"></svg>
<div class="panel" id="panel"><button class="close" id="close">×</button><div class="eyebrow">RELATIONSHIP DETAILS</div><h2 id="name"></h2><div class="path" id="path"></div><div class="relations" id="relations"></div></div>
<div class="tools"><button class="btn" id="center">CENTER</button><button class="btn" id="collapse">COLLAPSE</button><button class="btn" id="refresh">RESCAN</button></div><div class="hint">Click a group to open • click a file to inspect • drag to move • wheel to zoom</div><div class="status"><span class="led"></span>SERVER <b id="hb">LIVE</b></div>
<script>
const DATA=<?php echo json_encode($D,JSON_UNESCAPED_SLASHES);?>;const svg=document.getElementById('map'),NS='http://www.w3.org/2000/svg';let W=innerWidth,H=innerHeight,zoom=.82,panX=0,panY=0,selected=null,hover=null,open=null,drag=false,lastX=0,lastY=0,nodes=[],links=[];
const $=id=>document.getElementById(id);const esc=s=>String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
function rootNames(){const s=new Set();DATA.files.forEach(f=>s.add(f.split('/')[0]));DATA.dirs.forEach(d=>s.add(d.split('/')[0]));return [...s].sort()}
function childDirs(p){return DATA.dirs.filter(d=>d.startsWith(p+'/')&&!d.slice(p.length+1).includes('/'))}
function childFiles(p){return DATA.files.filter(f=>f.startsWith(p+'/')&&!f.slice(p.length+1).includes('/'))}
function mk(path,type){return{path,type,name:type==='root'?path+' /':type==='dir'?path.split('/').pop()+' /':path.split('/').pop(),x:0,y:0,w:type==='root'?190:type==='dir'?160:145,h:type==='root'?46:type==='dir'?34:28}}
function prepare(){nodes=[];links=[];const roots=rootNames();roots.forEach(r=>nodes.push(mk(r,'root')));if(!open)return;const root=nodes.find(n=>n.path===open)||nodes[0];if(!root)return;childDirs(root.path).forEach(d=>nodes.push(mk(d,'dir')));childFiles(root.path).forEach(f=>nodes.push(mk(f,'file')));const d=nodes.filter(n=>n.type==='dir');d.forEach(f=>{childDirs(f.path).forEach(v=>nodes.push(mk(v,'dir')));childFiles(f.path).forEach(v=>nodes.push(mk(v,'file')))});const visible=new Set(nodes.map(n=>n.path));DATA.refs.forEach(r=>{if(visible.has(r.from)&&visible.has(r.to))links.push({a:r.from,b:r.to,dep:true})});
const rootNode=root;d.forEach(n=>links.push({a:rootNode.path,b:n.path,dep:false}));childFiles(root.path).forEach(f=>links.push({a:rootNode.path,b:f,dep:false}));d.forEach(folder=>{childFiles(folder.path).forEach(f=>links.push({a:folder.path,b:f,dep:false}));childDirs(folder.path).forEach(v=>links.push({a:folder.path,b:v,dep:false}))});
layout()}
function layout(){const cx=W/2,cy=H/2;if(!open){nodes.forEach((n,i)=>{const a=i/Math.max(1,nodes.length)*Math.PI*2-.5;n.x=cx+Math.cos(a)*Math.min(W*.3,420);n.y=cy+Math.sin(a)*Math.min(H*.3,250)});return}const root=nodes.find(n=>n.path===open);root.x=cx;root.y=cy;const kids=nodes.filter(n=>n!==root&&n.type==='dir'&&n.path.split('/').length===2);kids.forEach((n,i)=>{const a=-Math.PI/2+i/Math.max(1,kids.length)*Math.PI*2;n.x=cx+Math.cos(a)*260;n.y=cy+Math.sin(a)*190});const direct=nodes.filter(n=>n!==root&&n.type==='file'&&n.path.split('/').length===2);direct.forEach((n,i)=>{n.x=cx-360;n.y=cy-(Math.min(direct.length,20)-1)*18+i*36});nodes.filter(n=>n.type==='file'&&n.path.split('/').length>2).forEach((n,i)=>{const parent=n.path.split('/').slice(0,-1).join('/');const p=nodes.find(v=>v.path===parent)||root;const same=nodes.filter(v=>v.type==='file'&&v.path.startsWith(parent+'/'));const j=same.indexOf(n);n.x=p.x+230;n.y=p.y-(same.length-1)*16+j*32});nodes.filter(n=>n.type==='dir'&&n.path.split('/').length>2).forEach((n,i)=>{const parent=n.path.split('/').slice(0,-1).join('/');const p=nodes.find(v=>v.path===parent)||root;n.x=p.x+230;n.y=p.y+i*42})}
function pos(n){return{x:n.x*zoom+panX,y:n.y*zoom+panY}}
function curve(a,b){const A=pos(a),B=pos(b),mx=(A.x+B.x)/2;return`M${A.x} ${A.y} C${mx} ${A.y} ${mx} ${B.y} ${B.x} ${B.y}`}
function connected(n){if(!selected)return false;return n.path===selected.path||links.some(e=>(e.a===selected.path&&e.b===n.path)||(e.b===selected.path&&e.a===n.path))}
function render(){prepare();svg.innerHTML='';const by=new Map(nodes.map(n=>[n.path,n]));const gW=document.createElementNS(NS,'g');links.forEach(e=>{const a=by.get(e.a),b=by.get(e.b);if(!a||!b)return;const p=document.createElementNS(NS,'path');p.setAttribute('d',curve(a,b));p.setAttribute('class',((selected&& (e.a===selected.path||e.b===selected.path))?'active ':'')+(e.dep?'dep':'wire'));gW.appendChild(p)});svg.appendChild(gW);const gN=document.createElementNS(NS,'g');nodes.forEach(n=>{const P=pos(n),on=n===hover||connected(n)||n===selected;const g=document.createElementNS(NS,'g');g.classList.add('node');const r=document.createElementNS(NS,'rect');r.setAttribute('x',P.x-n.w/2);r.setAttribute('y',P.y-n.h/2);r.setAttribute('width',n.w);r.setAttribute('height',n.h);r.setAttribute('rx','8');r.setAttribute('class',n.type==='root'?'root':n.type==='dir'?'folder':'file');if(on)r.classList.add('active');g.appendChild(r);const t=document.createElementNS(NS,'text');t.setAttribute('x',P.x);t.setAttribute('y',P.y+3);t.setAttribute('text-anchor','middle');t.setAttribute('font-family','ui-monospace,monospace');t.setAttribute('font-size',n.type==='root'?'10':n.type==='dir'?'8.5':'8');t.setAttribute('fill',on?'#efffff':n.type==='root'?'#76ddd3':n.type==='dir'?'#a79af0':'#82969e');t.textContent=(n.type==='root'?'▣ ':n.type==='dir'?'▰ ':'')+n.name;g.appendChild(t);if(n.type!=='file'){const c=document.createElementNS(NS,'text');c.setAttribute('x',P.x);c.setAttribute('y',P.y+16);c.setAttribute('text-anchor','middle');c.setAttribute('font-family','ui-monospace,monospace');c.setAttribute('font-size','7');c.setAttribute('fill','#506974');c.textContent=n.type==='root'?childDirs(n.path).length+' groups • '+childFiles(n.path).length+' files':'group';g.appendChild(c)}g.addEventListener('click',e=>{e.stopPropagation();select(n)});gN.appendChild(g)});svg.appendChild(gN);$('files').textContent=DATA.files.length;$('rels').textContent=DATA.refs.length;$('loader').style.display='none'}
function select(n){if(!n){selected=null;open=null;$('panel').classList.remove('show');render();return}selected=n;if(n.type==='root'||n.type==='dir'){open=n.path}$('panel').classList.add('show');$('name').textContent=n.name;$('path').textContent=n.path;const rr=DATA.refs.filter(r=>r.from===n.path||r.to===n.path||r.from.startsWith(n.path+'/')||r.to.startsWith(n.path+'/'));$('relations').innerHTML='<b>'+rr.length+' actual relationships</b><br>'+rr.slice(0,100).map(r=>'↳ '+esc(r.from)+' → '+esc(r.to)).join('<br>');render()}
function hit(x,y){let best=null,bd=22;nodes.forEach(n=>{const p=pos(n),d=Math.hypot(x-p.x,y-p.y);if(d<bd){bd=d;best=n}});return best}
svg.addEventListener('pointerdown',e=>{drag=true;lastX=e.clientX;lastY=e.clientY;svg.classList.add('drag')});addEventListener('pointermove',e=>{if(drag){panX+=e.clientX-lastX;panY+=e.clientY-lastY;lastX=e.clientX;lastY=e.clientY;render()}else{const h=hit(e.clientX,e.clientY);if(h!==hover){hover=h;render()}}});addEventListener('pointerup',()=>{drag=false;svg.classList.remove('drag')});svg.addEventListener('click',()=>select(null));svg.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.35,Math.min(2.5,zoom*(e.deltaY<0?1.1:.9)));render()},{passive:false});$('close').onclick=()=>select(null);$('collapse').onclick=()=>select(null);$('center').onclick=()=>{zoom=.82;panX=0;panY=0;render()};$('refresh').onclick=()=>location.reload();$('search').oninput=e=>{const q=e.target.value.toLowerCase().trim();if(!q){select(null);return}const path=DATA.files.find(f=>f.toLowerCase().includes(q))||DATA.dirs.find(d=>d.toLowerCase().includes(q))||rootNames().find(r=>r.toLowerCase().includes(q));if(path){const type=DATA.files.includes(path)?'file':DATA.dirs.includes(path)?'dir':'root';select(mk(path,type))}};addEventListener('keydown',e=>{if(e.key==='Escape')select(null)});
function heartbeat(){fetch(location.pathname+'?pulse=1&t='+Date.now(),{cache:'no-store'}).then(r=>r.json()).then(d=>{$('hb').textContent=d.time;$('state').textContent='LIVE'}).catch(()=>{$('hb').textContent='OFFLINE';$('state').textContent='OFFLINE'})}addEventListener('resize',()=>{W=innerWidth;H=innerHeight;render()});render();heartbeat();setInterval(heartbeat,3000);
</script></body></html>